INSERT INTO feature VALUES('package-address','modules','A package''s address','packages','implemented','ordinary',NULL,'A package''s address is the BLAKE3 digest, over its package source and then each module by its path, of each item the source itself declares in admission order, as its dotted path and its content key, every inert component of its models left out, and then of each dependency''s address, read back through the store from the pointer its lock records, never their aliases or coordinates: an edit to an inert field leaves the address and every other item''s key, and an edit to a content item, its own or a dependency''s, or to what its model asks of the toolchain, moves it; a declaration the lowering refused, or an item whose content holds an unresolved node, leaves the package unaddressed, named by the item, and a pointer the store cannot read back, named by the dependency''s coordinate. `gandr check` prints it on each reconciled manifest''s line, `manifest: <path>: <what> (address <hex>)`, and `package.gandr.toml` does not carry it.','surface-dispatcher surface-driver','crates/surface-dispatcher/tests/package.rs::an_inert_edit_leaves_the_address_and_a_content_edit_moves_it_3030 crates/surface-dispatcher/tests/package.rs::every_corpus_package_s_address_ignores_its_inert_fields_3030 crates/surface-driver/tests/cli.rs::a_package_s_manifest_is_written_and_drift_refused_2687 crates/surface-dispatcher/tests/package.rs::a_lock_is_written_once_and_reads_alike_from_anywhere_3072 crates/surface-dispatcher/tests/package.rs::a_pointer_the_store_cannot_answer_leaves_the_dependent_unaddressed_3157','corpus/ledger/features/package-address.gandr',NULL);
